const products=[
{name:'Anti Acne Gel',category:'skin',type:'FACE CARE',shape:'jar',label:'Anti Acne<br>Gel',description:'Explore Belif’s Anti Acne Gel. Ask Nazia about its ingredients, how to use it and whether it fits your routine.'},
{name:'Glow Body Lotion',category:'skin',type:'BODY CARE',shape:'bottle',label:'Glow Body<br>Lotion',description:'The Glow & Brightening Body Lotion is part of Belif’s body-care collection. Enquire about the formulation and available sizes.'},
{name:'Onion & Bhringraj',category:'hair',type:'HERBAL HAIR MASK',shape:'jar',label:'Onion &<br>Bhringraj',description:'A hair mask listed with onion, bhringraj, aloe vera, fenugreek and hibiscus. Confirm the complete ingredient list and directions with Nazia.'},
{name:'Handmade Soaps',category:'skin',type:'BATH & BODY',shape:'jar',label:'Handmade<br>Soaps',description:'Discover the handmade soap selection. Ask Nazia about current variants and choose a little everyday ritual.'},
{name:'Herbal Hair Powder',category:'hair',type:'HAIR CARE',shape:'jar',label:'Herbal Hair<br>Powder',description:'Explore Belif’s herbal hair-care powder. Ask for ingredient details, preparation and usage guidance before choosing.'},
{name:'Custom Gift Hampers',category:'gifts',type:'THOUGHTFUL GIFTING',shape:'bottle',label:'A Little<br>Care',description:'Create a custom gift hamper with Nazia. Share the occasion, preferred products and delivery requirements to explore the options.'}];
const enquiry=name=>'https://wa.me/919145562289?text='+encodeURIComponent('Hi Nazia! I would like to know more about '+name+'. Please share the available options and details.');
document.querySelectorAll('[data-enquiry]').forEach(a=>{a.href=enquiry(a.dataset.enquiry);a.target='_blank';a.rel='noopener'});
const jar=p=>`<div class="jar"><div class="lid"></div><div class="jar-body"><span>belif</span><small>BY NAZIA SAYED</small><i>${p.label}</i></div></div>`;
const bottle=p=>`<div class="bottle"><div class="cap"></div><div class="neck"></div><div class="glass"><div class="label"><span>belif</span><small>BY NAZIA SAYED</small><i>${p.label}</i><b>YOUR EVERYDAY RITUAL</b></div></div></div>`;
document.querySelector('#products').innerHTML=products.map((p,i)=>`<article class="product reveal" data-category="${p.category}"><div class="product-visual" role="img" aria-label="Illustrative packaging concept for ${p.name}">${p.shape==='jar'?jar(p):bottle(p)}</div><div class="product-meta"><div><p>${p.type}</p><h3>${p.name}</h3></div><button data-product="${i}" aria-label="View ${p.name}">↗</button></div></article>`).join('');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('.product').forEach(p=>{p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter;if(!p.hidden)count++});document.querySelector('#filter-status').textContent=count+' products shown'}));
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{const p=products[Number(b.dataset.product)];document.querySelector('#dialog-title').textContent=p.name;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-link').href=enquiry(p.name);dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));if(!reduced.matches)document.body.classList.add('motion-enabled');
const motion=document.querySelector('#motion');let paused=reduced.matches;function setMotion(){document.body.classList.toggle('paused',paused);motion.textContent=paused?'Enable motion':'Pause motion';motion.setAttribute('aria-pressed',String(paused))}setMotion();motion.addEventListener('click',()=>{paused=!paused;setMotion()});
const art=document.querySelector('.hero-art');art.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=art.getBoundingClientRect();art.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-9+'deg');art.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*12+'deg')});art.addEventListener('pointerleave',()=>{art.style.setProperty('--rx','0deg');art.style.setProperty('--ry','0deg')});let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--progress',(max?scrollY/max*100:0)+'%');ticking=false})},{passive:true});
